using Dogity.Domain.Sports;
using Microsoft.EntityFrameworkCore;

namespace Dogity.Infrastructure.Persistence.Seed;

/// <summary>
/// Rally Obedience (Paket RO1, 2026-10-22): die FCI International Class und die
/// nationalen Klassen von VDH (RO B, RO 1, RO 2, RO 3, RO S) und ÖKV (RO B, RO 1,
/// RO 2, RO 3, RO S).
///
/// Eine Sportart <c>RALLYO</c> für alle elf Ordnungen. Die Übungen sind
/// trainierbare Schildgruppen und nicht die einzelnen Schilder: Die Kataloge
/// zählen 89 (FCI), 132 (VDH) und 105 (ÖKV) Schilder, im Tagebuch wäre jedes
/// einzelne unbrauchbar, und eine "Spirale rechts" gleicht der "Spirale links"
/// bis auf die Seite. Jedes Schild gehört zu genau einer Gruppe, nach seiner
/// Hauptaufgabe: Verbindet ein Schild mehrere Aufgaben, entscheidet die
/// anspruchsvollste (Hürde, Distanz, Abruf, Position aus der Bewegung,
/// Seitenwechsel, Rückwärtsgehen, Vorsitz, Wendung, Position am Halt;
/// Schritte rückwärts im Vorsitz zählen als Rückwärtsgehen). Je Ordnung steht
/// im Hinweis der Ordnungs-Übung, welche Schilder dieser Klasse zur Gruppe
/// gehören, mit der Nummer und Bezeichnung der jeweiligen Ordnung und der
/// Seite. Gruppen, die es in der Klasse nicht gibt, hängen nicht an ihr.
///
/// Gewertet wird nicht über Punkte je Übung, sondern über Abzüge vom Startwert
/// 100: Die Übungen tragen deshalb wie beim Agility und beim Hoopers 0 Punkte,
/// die Bewertung steht in der Beschreibung der Ordnung und in den Hinweisen.
///
/// Geltungsbereich je Ordnung ausdrücklich: Die FCI-Ordnung gilt überall
/// (<c>Ueberall</c>), die übrigen tragen "DE" bzw. "AT". Die Sportart steht in
/// <see cref="FciKatalog.InternationaleSportarten"/> und ist in jedem Land
/// sichtbar. Englische Namen und Texte (<see cref="FciKatalog"/>,
/// <see cref="FciTexteEn"/>) gibt es nur für die FCI-Ordnung und die Gruppen,
/// die sie führt; "Bogen und Zickzack" und "Mehrschildübung" kennen nur die
/// nationalen Ordnungen und bleiben deutsch. Die Schilder der FCI-Ordnung
/// stehen mit ihren englischen Originalbezeichnungen im deutschen Text, weil
/// bei FCI-Prüfungen die englischen Schilder vorgeschrieben sind.
///
/// Quellen (siehe docs/PO_VERIFIKATION.md, Abschnitt "Rally Obedience"): jede
/// Ordnung und Gruppe nennt die Seite, wie sie im Dokument steht (beim VDH die
/// Nummer im Seitenfuß, beim ÖKV die Nummer in der Kopfzeile der Seite). Die
/// VDH-Ordnung gilt ab 01.01.2027; bis 31.12.2026 gilt noch die Fassung von
/// 2017, hinterlegt ist wie beim Hoopers die künftige. Die Texte sind eigene
/// Beschreibungen, keine Kopie der Ordnungen.
///
/// Bestand: Der Seeder läuft auch gegen eine Datenbank, in der es schon eine
/// Sportart "Rally Obedience" gibt. Gefunden wird die globale Sportart (ohne
/// Verein) mit dem Code <c>RALLYO</c>; fehlt sie, wird eine globale Sportart mit
/// dem Namen "Rally Obedience" unter ihrem Code mitgenutzt (nicht doppelt
/// angelegt). Eine Vereinssportart gleichen Namens oder Codes bleibt unberührt.
/// Vorhandene Übungen werden wie überall nur ergänzt, nie überschrieben.
/// </summary>
public static partial class SportCatalogSeeder
{
    private const string QuelleFciRallyObedience = "https://fci.be/medias/FCI-ROB-REG-2025-en-19918.pdf";
    private const string QuelleVdhRallyObedience = "https://www.schaeferhunde.de/fileadmin/Secure/Satzungen_Ordnungen/02-VDH_RO_RW_2027.pdf";
    private const string QuelleOekvRallyObedience = "https://rally-obedience.oekv.at/media/upload/editor/files/Rally-Obedience/Endfassung_RO_PO_2023_20012023.pdf";

    private static async Task<Sport> SeedRallyObedienceAsync(ApplicationDbContext db)
    {
        var rally = await SeedSportAsync(db, await GlobaleSportCodeAsync(db, FciKatalog.RallyObedienceCode, "Rally Obedience"), "Rally Obedience",
